const { fork } = require('child_process');
const LIMITE = 4;            // tope de concurrencia de la "cuenta" de juguete
const ENTORNOS = [];         // {proc, ocupado}
const log = [];
const t0 = Date.now();
const ahora = () => Date.now() - t0;
let creados = 0;
function pedir(id, dur) {
  return new Promise((res) => {
    const inicio = ahora();
    let e = ENTORNOS.find((x) => !x.ocupado && x.listo);
    if (e) { return usar(e, 'reuso', 0); }
    if (ENTORNOS.length >= LIMITE) { log.push({ id, r: 'THROTTLE', t: inicio }); return res(); }
    const proc = fork(__dirname + '/worker.js');
    e = { proc, ocupado: true, listo: false, n: ++creados };
    ENTORNOS.push(e);
    proc.once('message', (m) => { e.listo = true; e.initMs = m.initMs; usar(e, 'FRIO', Date.now() - t0 - inicio); });
    function usar(e, tipo, espera) {
      e.ocupado = true;
      const ini2 = ahora();
      e.proc.send({ id, dur });
      e.proc.once('message', (m) => { e.ocupado = false; log.push({ id, r: tipo, env: e.n, esperaArranque: Math.round(espera), total: ahora() - inicio, t: inicio }); res(); });
    }
  });
}

// Concurrencia serverless en tiempo virtual (microsegundos enteros).
// Regla del modelo: un entorno atiende UN pedido a la vez; si todos están ocupados, hay que crear otro (arranque en frío).
function simular({ rps, durMs, segundos, limite, previos = 0 }) {
  const libreEn = Array(previos).fill(0);       // instante (µs) en que cada entorno queda libre
  let frios = 0, rechazados = 0, pico = 0, atendidos = 0;
  const paso = Math.round(1e6 / rps), dur = durMs * 1000;
  for (let t = 0; t < segundos * 1e6; t += paso) {
    let e = libreEn.findIndex((l) => l <= t);
    if (e === -1) {
      if (libreEn.length >= limite) { rechazados++; continue; }
      libreEn.push(0); e = libreEn.length - 1; frios++;
    }
    libreEn[e] = t + dur; atendidos++;
    pico = Math.max(pico, libreEn.filter((l) => l > t).length);
  }
  return { entornos: libreEn.length, frios, rechazados, atendidos, pico };
}
const casos = [
  ['100 pedidos/s de 1000 ms', 100, 1000],
  ['100 pedidos/s de 500 ms', 100, 500],
  ['200 pedidos/s de 250 ms', 200, 250],
  ['2000 pedidos/s de 200 ms', 2000, 200],
];
for (const [n, rps, durMs] of casos) {
  const r = simular({ rps, durMs, segundos: 5, limite: 1000 });
  console.log(n.padEnd(26), 'fórmula', String(rps * durMs / 1000).padStart(4),
    '| pico simulado', String(r.pico).padStart(4), '| arranques en frío', String(r.frios).padStart(4), '| rechazados', r.rechazados);
}
let r = simular({ rps: 2000, durMs: 200, segundos: 5, limite: 300 });
console.log('2000/s de 200 ms con tope 300 ->', JSON.stringify(r), '(fórmula pide 400)');
