// Precios de lista de AWS Lambda, x86, us-east-1, archivo oficial publicado el 2026-11-11 (USD)
const GBS = 0.0000166667;          // por GB-segundo de ejecución (primer tramo)
const PC_RESERVA = 0.0000041667;   // por GB-segundo de concurrencia aprovisionada configurada (esté usada o no)
const PC_EJEC = 0.0000097222;      // por GB-segundo ejecutando sobre concurrencia aprovisionada
const MES = 30 * 86400;            // 2.592.000 s
const gb = (mb) => mb / 1024;

// 1) Cuánto cuesta DEJAR N entornos listos todo el mes, usen o no
for (const [n, mb] of [[1, 1024], [5, 512], [50, 512]]) {
  console.log(`reservar ${String(n).padStart(2)} entornos de ${String(mb).padStart(4)} MB: USD ${(n * gb(mb) * MES * PC_RESERVA).toFixed(2)} por mes, sin un solo pedido`);
}
// 2) Cuánto cuestan los arranques en frío en plata (la fase Init se factura)
const frios = 1_000_000, initMs = 400, mb = 512;
console.log(`1.000.000 de arranques en frío de ${initMs} ms con ${mb} MB: USD ${(frios * initMs / 1000 * gb(mb) * GBS).toFixed(2)} de Init facturado`);
// 3) La misma hora de ejecución, con y sin aprovisionada (solo la parte de ejecución)
const seg = 3600, g = gb(512);
console.log(`1 h de ejecución a 512 MB: bajo demanda USD ${(seg * g * GBS).toFixed(4)}, sobre aprovisionada USD ${(seg * g * PC_EJEC).toFixed(4)} (más la reserva)`);
// 4) Desde qué uso sale más barato tener la reserva (por GB-s realmente ejecutado)
const u = PC_RESERVA / (GBS - PC_EJEC);
console.log(`la reserva compensa el precio si los entornos reservados están ejecutando más del ${(u * 100).toFixed(0)} % del tiempo`);
